scwin.fn_tmpDeptFilter = function(cellData, tmpParam, rowIdx) {
    //cellData는 웹스퀘어 엔진에서 넘겨주는 cell의 데이터로 colIndex에 설정한 컬럼의 데이터이다.
    //tmpParam은 setColumnFilter API를 호출 할 때 파라메터로 넘겨주는 param의 값이다.
    //rowIdx는 웹스퀘어 엔진에서 넘겨주는 row의 index값이다.
    if (cellData.indexOf('IT') > -1) {
        return true;
    } else if (cellData.indexOf('인사') > -1) {
        return true;
    }
    return false; //return이 true인 경우 적용하고 false인 경우 skip한다.
}
