scwin.cal = function(data, formatData, row, col) {
    //'20160822120000'
    //'2016/08/22 12:00:00'
    return data.substr(0, 4) + '/' + data.substr(4, 2) + '/' + data.substr(6, 2) + ' ' + data.substr(8, 2) + ':' + data.substr(10, 2) + ':' + data.substr(12, 2);
}
